ude('services._order-field',['field'=>$field])@endforeach</div>@endforeach<button class="btn btn-primary">Criar ordem</button></form></section><script>document.addEventListener('DOMContentLoaded',()=>{const s=document.getElementById('service-version'),a=document.getElementById('associate-select'),n=document.getElementById('member-note'),sync=()=>{const required=s.options[s.selectedIndex]?.dataset.membersOnly==='1';a.required=required;n.textContent=required?'(obrigatório para este serviço)':'(opcional)';document.querySelectorAll('[data-version-fields]').forEach(el=>{const show=el.dataset.versionFields===s.value;el.hidden=!show;el.style.display=show?'grid':'none';el.querySelectorAll('input,select,textarea').forEach(i=>i.disabled=!show) })};s.addEventListener('change',sync);sync()})</script>@endsection
